mapper.select:
SELECT q.id, q.content, q.question_type AS questionType, q.option_a AS optionA, q.option_b AS optionB, q.option_c AS optionC, q.option_d AS optionD, q.answer, q.analysis, q.difficulty, q.subject, u.real_name AS creatorName, q.create_time AS createTime, q.update_time AS updateTime FROM question q LEFT JOIN user u ON q.creator_id = u.id
AND q.question_type = #{query.questionType}
AND q.difficulty = #{query.difficulty}
AND q.subject = #{query.subject}
AND q.content LIKE CONCAT('%', #{query.keyword}, '%')
AND q.id IN ( SELECT bi.question_id FROM question_bank_item bi WHERE bi.bank_id = #{query.bankId} )
ORDER BY q.create_time DESC
